use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    ensures
        // (1) length is the sum of lengths
        res@.len() == a@.len() + b@.len(),

        // (2) first part equals `a`
        forall|i: int|
            0 <= i < a@.len() ==> res@[i] == a@[i],

        // (3) second part equals `b` shifted by `a.len()`
        forall|j: int|
            0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut res = Vec::<f32>::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i as int <= a@.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
    {
        res.push(a[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < b.len()
        invariant
            0 <= j as int <= b@.len(),
            res@.len() == a@.len() + j as int,
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            forall|t: int| 0 <= t < j as int ==> res@[a@.len() + t] == b@[t],
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!